import time
from processor import process, transform

N = 10_000


def _items():
    return list(range(N))


def test_completeness():
    out = list(process(_items()))
    assert len(out) == N, f"expected {N} results, got {len(out)}"


def test_speed():
    start = time.perf_counter()
    out = list(process(_items()))
    elapsed = time.perf_counter() - start
    assert elapsed < 0.5, f"too slow: {elapsed:.3f}s"


def test_correctness():
    out = list(process([1, 2, 3]))
    assert out == [transform(1), transform(2), transform(3)]
